(() => {
    const targets = {
        "fetch": () => window.fetch,

        "XMLHttpRequest.open": () => XMLHttpRequest?.prototype?.open,
        "XMLHttpRequest.send": () => XMLHttpRequest?.prototype?.send,
        "XMLHttpRequest.setRequestHeader": () =>
            XMLHttpRequest?.prototype?.setRequestHeader,

        "WebSocket": () => window.WebSocket,
        "WebSocket.send": () => WebSocket?.prototype?.send,

        "EventSource": () => window.EventSource,

        "document.createElement": () => document.createElement,

        "Element.appendChild": () => Element?.prototype?.appendChild,
        "Element.insertBefore": () => Element?.prototype?.insertBefore,
        "Element.replaceChild": () => Element?.prototype?.replaceChild,

        "EventTarget.addEventListener": () =>
            EventTarget?.prototype?.addEventListener,
        "EventTarget.removeEventListener": () =>
            EventTarget?.prototype?.removeEventListener,

        "localStorage.setItem": () => Storage?.prototype?.setItem,
        "localStorage.getItem": () => Storage?.prototype?.getItem,

        "history.pushState": () => History?.prototype?.pushState,
        "history.replaceState": () => History?.prototype?.replaceState,

        "setTimeout": () => window.setTimeout,
        "setInterval": () => window.setInterval,
        "requestAnimationFrame": () => window.requestAnimationFrame,

        "performance.now": () => performance?.now,

        "eval": () => window.eval,
        "Function": () => window.Function,

        "Function.call": () => Function?.prototype?.call,
        "Function.apply": () => Function?.prototype?.apply,
        "Function.bind": () => Function?.prototype?.bind,

        "Object.defineProperty": () => Object.defineProperty,
        "Object.getOwnPropertyDescriptor": () =>
            Object.getOwnPropertyDescriptor,

        "crypto.getRandomValues": () =>
            crypto?.getRandomValues,

        "Canvas.toDataURL": () =>
            HTMLCanvasElement?.prototype?.toDataURL,

        "Canvas.getImageData": () =>
            CanvasRenderingContext2D?.prototype?.getImageData,

        "WebGL.getParameter": () =>
            WebGLRenderingContext?.prototype?.getParameter,
    };

    const results = [];

    for (const [name, getter] of Object.entries(targets)) {
        try {
            const fn = getter();

            if (typeof fn !== "function") {
                continue;
            }

            const source = Function.prototype.toString.call(fn);

            const suspicious =
                !source.includes("[native code]") ||
                fn.toString !== Function.prototype.toString;

            if (suspicious) {
                results.push({
                    api: name,
                    source
                });
            }
        } catch (e) {
            results.push({
                api: name,
                error: e.message
            });
        }
    }

    console.group("Modified APIs");

    if (!results.length) {
        console.log("No modifications detected.");
    }

    for (const result of results) {
        console.group(result.api);

        if (result.error) {
            console.log("ERROR:", result.error);
        } else {
            console.log(result.source);
        }

        console.groupEnd();
    }

    console.groupEnd();

    return results;
})();

